import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { socket } from "./socket"; // e.g., from
import './DMPage.css';

// Import a shared socket instance if you have one (otherwise this creates one)


const DMPage = ({ currentUser }) => {
  const navigate = useNavigate();
  const [messages, setMessages] = useState([]);            // All received messages
  const [newMessage, setNewMessage] = useState('');
  const [dmList, setDmList] = useState([]);                  // List of conversation users (with profile info)
  const [selectedChat, setSelectedChat] = useState(null);    // Currently selected conversation (user object)
  const messagesEndRef = useRef(null);

  // Scroll to latest message whenever messages change
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  // Register current user and set up socket listeners
  useEffect(() => {
    if (currentUser?._id) {
      console.log("Registering user on socket:", currentUser._id);
      socket.emit("register", currentUser._id);
    }

    // Receive a new message
    socket.on("receiveMessage", (message) => {
      console.log("Received message:", message);
      setMessages(prev => [...prev, message]);

      // Ensure the sender is in DM list if not already (request user details from server)
      if (!dmList.some(user => user._id === message.sender)) {
        console.log("Sender not in DM list. Requesting details for:", message.sender);
        socket.emit("addToDM", message.sender);
      }
    });

    // Listen for DM list updates (assumed to provide complete user info: _id, name, role, image)
    socket.on("addToDM", (newUser) => {
      console.log("Received addToDM event with user:", newUser);
      if (!dmList.some(user => user._id === newUser._id)) {
        setDmList(prev => [...prev, newUser]);
      }
    });

    // Listen for new conversation events
    socket.on("newConversation", (conversation) => {
      console.log("🆕 New conversation received:", conversation);
      // Determine the other participant based on currentUser
      const otherParticipantId = conversation.participants.find(u => u !== currentUser._id);
      // For simplicity, assume that the server sends full user info via addToDM or conversation object
      let existingUser = dmList.find(user => user._id === otherParticipantId);
      if (!existingUser) {
        // If not already in list, add a placeholder (you can later fetch details)
        console.log("Other participant not in DM list. Adding placeholder for:", otherParticipantId);
        setDmList(prev => [...prev, { _id: otherParticipantId, name: "Unknown", role: "applicant", image: "default_user_image.jpg" }]);
      }
      // Optionally, you can update a conversations state if needed.
    });

    return () => {
      socket.off("receiveMessage");
      socket.off("addToDM");
      socket.off("newConversation");
    };
  }, [currentUser, dmList]);

  // Handle sending a new chat message
  const handleSend = () => {
    if (newMessage.trim() && selectedChat) {
      const messageData = {
        sender: currentUser._id,
        receiver: selectedChat._id,
        message: newMessage,
      };
      console.log("Sending message:", messageData);
      socket.emit("sendMessage", messageData);
      setNewMessage('');
    }
  };

  // Handle accepting a conversation (for clients only)
  const handleAccept = () => {
    console.log("Accepting conversation with:", selectedChat);
    // Remove all other conversations from DM list (simulate "removing" other applicants)
    setDmList([selectedChat]);
    // Navigate to CreateTimeline.jsx (assuming the route is set up)
    navigate("/createTimeline");
  };

  return (
    <div className="dm-container">
      {/* Header Section with Navigation */}
      <div className="header">
        <img src="images/image10.png" alt="User" />
        <div className="header-right">
          <span onClick={() => navigate("/homes")}>Home</span>
          <span onClick={() => navigate("/profile")}>Profile</span>
          <span onClick={() => navigate("/ong-proj")}>Ongoing Projects</span>
          <span onClick={() => navigate("/post")}>Post a Job</span>
          <span onClick={() => navigate("/contact")}>Contact Us</span>
          <span onClick={() => navigate("/abt")}>About</span>
        </div>
      </div>

      <div className="dm-main">
        {/* Sidebar with DM List */}
        <div className="dm-sidebar">
          <h2>Conversations</h2>
          {dmList.map((user) => (
            <div 
              key={user._id} 
              className={`active-chat ${selectedChat && selectedChat._id === user._id ? "selected" : ""}`}
              onClick={() => {
                console.log("Selected conversation with:", user);
                setSelectedChat(user);
              }}
            >
              <div className="user-avatar">
                <img src={user.image || "default_user_image.jpg"} alt={user.name} />
              </div>
              <div className="user-info">
                <h3>{user.name}</h3>
                <p>{user.role}</p>
              </div>
            </div>
          ))}
        </div>

        {/* Chat Window */}
        <div className="chat-window">
          {selectedChat ? (
            <>
              <div className="messages-container">
                {messages
                  .filter(msg => (msg.sender === selectedChat._id || msg.receiver === selectedChat._id))
                  .map((msg, index) => (
                    <div key={index} className={`message ${msg.sender === currentUser._id ? 'sent' : 'received'}`}>
                      <div className="message-content">
                        <div className="message-header">
                          <span className="sender">
                            {msg.sender === currentUser._id ? "You" : selectedChat.name}
                          </span>
                          <span className="timestamp">{new Date().toLocaleTimeString()}</span>
                        </div>
                        <p>{msg.message}</p>
                      </div>
                    </div>
                  ))}
                <div ref={messagesEndRef} />
              </div>

              <div className="message-input">
                <input
                  type="text"
                  value={newMessage}
                  onChange={(e) => setNewMessage(e.target.value)}
                  placeholder="Type your message..."
                  onKeyPress={(e) => e.key === 'Enter' && handleSend()}
                />
                <button onClick={handleSend}>
                  <svg viewBox="0 0 24 24" width="24" height="24">
                    <path fill="currentColor" d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/>
                  </svg>
                </button>
              </div>

              {/* If current user is a client, show the Accept button */}
              {currentUser.role === "client" && (
                <div className="accept-section">
                  <button onClick={handleAccept} className="accept-btn">
                    Accept
                  </button>
                </div>
              )}
            </>
          ) : (
            <div className="empty-chat">
              <p>Select a conversation to start chatting</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default DMPage;
